import os
import re

def load_grids():
    """Load all demo pairs from session log"""
    d = os.environ['RLM_SESSION_DIR']
    session_file = os.path.join(d, '../sessions/' + os.path.basename(d) + '.jsonl')

    G = {}
    in_demo = False
    demo_content = {}

    with open(session_file, 'r') as f:
        for line in f:
            line = line.strip()

            # Check for task instance header
            if re.match(r'.*Demo.*', line, re.IGNORECASE):
                # End previous demo if any
                if in_demo:
                    if 'output' in demo_content and 'input' in demo_content and demo_content['input']:
                        key = list(demo_content.keys())[0]
                        if key not in G:
                            G[key] = []
                        G[key].append({
                            'input': demo_content['input'],
                            'output': demo_content['output']
                        })

                in_demo = True
                demo_content = {}
            elif in_demo:
                # Accumulate demo content
                demo_content.update(line)
                in_demo = False

    # Handle last demo
    if in_demo:
        if 'output' in demo_content and 'input' in demo_content and demo_content['input']:
            key = list(demo_content.keys())[0]
            if key not in G:
                G[key] = []
            G[key].append({
                'input': demo_content['input'],
                'output': demo_content['output']
            })

    return G

